  vendas: { nome: 'vendas no site', meta: 'Vendas ➜ Site (precisa do Pixel do Meta)', otimizacao: 'Maximizar conversões (Compra)', botao: 'Comprar agora', botoes: ['Comprar agora', 'Pedir agora', 'Saiba mais', 'Ver cardápio', 'Reservar'], resultado: 'compra' },
  cadastros: { nome: 'cadastros (leads)', meta: 'Cadastros ➜ Site (a página de destino deste fluxo)', otimizacao: 'Maximizar cadastros', botao: 'Cadastre-se', botoes: ['Cadastre-se', 'Saiba mais', 'Agendar'], resultado: 'cadastro' },
  loja: { nome: 'visitas à loja', meta: 'Reconhecimento ➜ Alcance (pessoas perto da loja)', otimizacao: 'Alcance', botao: 'Como chegar', botoes: ['Como chegar', 'Ligar agora', 'Saiba mais'], resultado: 'pessoa alcançada perto da loja' },
};
const CP_BOTOES = ['Enviar mensagem', 'Saiba mais', 'Comprar agora', 'Cadastre-se', 'Pedir agora', 'Ver cardápio', 'Agendar', 'Ligar agora', 'Como chegar', 'Reservar'];
// categorias especiais do Meta: idade 18–65+, sem escolher gênero, raio mínimo de ~25 km (15 milhas), segmentação detalhada limitada
const CP_ESPECIAIS = { credito: 'crédito e serviços financeiros', emprego: 'emprego e vagas', moradia: 'imóveis e moradia', politica: 'questões sociais, eleições ou política' };
const CP_MIN_DIA = 6;   // verba mínima por conjunto por dia (R$) para o Meta entregar com folga
// ângulos de criativo: "prova" só com prova social do anunciante; sem ela, "curiosidade"
const cpAngulos = V => ['dor', 'desejo', 'oferta', V.dados.prova ? 'prova' : 'curiosidade'];
const CP_ANGULO_NOME = { dor: 'Dor (o problema)', desejo: 'Desejo (o resultado)', oferta: 'Oferta (condição)', prova: 'Prova (quem já usou)', curiosidade: 'Curiosidade (pergunta)' };

// anúncios do copywriter (ou do revisor) na ordem fixa dos ângulos, cada campo no tamanho do Meta
function cpNormaliza(r, V) {
  const lista = r && Array.isArray(r.angulos) ? r.angulos.filter(a => a && typeof a === 'object') : [];
  return cpAngulos(V).map((tipo, i) => {
    const a = lista.find(x => cpSemAcento(x.tipo) === tipo) || lista[i] || {};
    return { tipo, nome: cpL(a.nome, 60) || CP_ANGULO_NOME[tipo], principal_a: cpP(a.principal_a, 700), principal_b: cpP(a.principal_b, 700),
      titulo: cpL(a.titulo, 40), descricao: cpL(a.descricao, 30), botao: CP_BOTOES.includes(a.botao) ? a.botao : '', frase_arte: cpL(a.frase_arte, 44), imagem: cpT(a.imagem, 500) };
  });
}
// ── trava de política (código): o que derruba anúncio no Meta e o que o anunciante não disse ──
// atributo pessoal ("Você está acima do peso?", "Você tem dívidas?") é proibido pelo Meta
const CP_TERMOS = 'acima do peso|gord|obes|quilos a mais|endivid|d[ií]vida|nome sujo|negativad|depress|ansios|ansiedade|diab[eé]t|calv|careca|soltei|divorc|desempreg|pobre|doen[çc]a|c[aâ]ncer|gr[aá]vida|evang[eé]lic|cat[oó]lic|gay|l[eé]sbic|idos|velh|' +
  'dor\\b|dores|coluna|lombar|postura ruim|h[eé]rnia|artrite|artrose|enxaqueca|ins[oô]nia|estresse|celulite|estrias?|flacidez|rugas|acne|espinhas|queda de cabelo|impot[eê]n|disfun|menopausa|colesterol|press[aã]o alta|hipertens|v[ií]cio|alco[oó]l|fumante';
// "Você sofre com dor nas costas?", "Você está acima do peso?" e "Cansada de dor nas costas?" (insinua que a pessoa tem)
const CP_ATRIBUTO = new RegExp('\\b(voc[eê]s?|vc|tu)\\s+(est[aá]|tem|[eé]|sofre|anda|vive|ficou|t[aá])\\b[^.!?]{0,40}\\b(' + CP_TERMOS + ')|^\\s*(cansad[oa]s?|sofrendo|ainda sofre)\\s+(de|com)\\b[^.!?]{0,40}\\b(' + CP_TERMOS + ')[^.!?]*\\?', 'i');
const CP_PROMESSA = /(garantid[oa]s?\b|100% (garantid|segur|eficaz|aprovad)|\bcura\b|\bcurar\b|emagre[çc]a \d|perca \d+ ?(kg|quilos)|ganhe (dinheiro|R\$)|renda extra|fique ric|resultado imediato|sem (nenhum )?esfor[çc]o|antes e depois|milagr)/i;
const CP_URGENCIA = /s[oó] hoje|somente hoje|[uú]ltim[ao]s (unidades|horas|dias|vagas)|acaba hoje|corr[ae] que acaba|por tempo limitado|enquanto durar/i;
const cpTiraFrases = (t, teste) => cpFrases(t).filter(f => !teste(f)).join(' ').trim();
// limpa um texto: tira a FRASE com o problema (e conta o que tirou)
function cpTrava(texto, V, onde, trava) {
  const d = V.dados, permitidos = new Set([...cpValores(d.preco), ...cpValores(d.oferta), ...(cpNum(d.preco) !== null && !/R\$/.test(d.preco || '') ? [Math.round(cpNum(d.preco) * 100)] : [])]);
  let t = String(texto || '').split('\n').map(l => l.replace(/[ \t]+/g, ' ').trim()).join('\n').replace(/\n{3,}/g, '\n\n').trim();
  const regras = [
    [f => CP_ATRIBUTO.test(f), 'atributo pessoal ("você está/tem…"), proibido pelo Meta'],
    [f => CP_PROMESSA.test(f), 'promessa que o Meta recusa (garantido, cura, ganho, antes e depois)'],
    [f => cpValores(f).some(c => !permitidos.has(c)), 'preço que o anunciante não deu'],
    [f => !d.validade && CP_URGENCIA.test(f), 'urgência que o anunciante não deu'],
  ];
  for (const [teste, motivo] of regras) {
    const antes = t;
    // linha por linha: o texto do anúncio tem parágrafos e linhas com emoji
    t = t.split('\n').map(l => {
      if (!l.trim()) return '';
      const x = cpTiraFrases(l, teste);
      return x !== l.trim() && !/[\p{L}\d]/u.test(x) ? '' : x;   // cortou a frase e sobrou só o emoji dela: a linha sai
    }).join('\n').replace(/\n{3,}/g, '\n\n').trim();
    if (t !== antes.trim()) trava.push(`${onde}: tirei frase com ${motivo}`);
  }
  return t;
}

// Aplica a revisão de políticas: vale o texto do revisor (campo vazio = o do copywriter). Trava em código: atributo pessoal, promessa, preço e urgência saem;
// botão só da lista do objetivo. Monta os links com UTM de cada anúncio em cada público e a mensagem do WhatsApp com o código do anúncio.
const V = $('🧩 Confere o pedido').first().json, E = $('🧩 Lê a estratégia').first().json.estrategia, C = $('🧩 Lê os textos').first().json;
const d = V.dados, op = V.op, O = CP_OBJETIVOS[op.objetivo];
let rv = null;
try { rv = parseJSON($('🤖 Revisor de políticas').first().json.output); } catch (e) {}
const doRev = cpNormaliza(rv, V), doCopy = C.textos.angulos, trava = [];
const frase6 = t => String(t || '').split(/\s+/).filter(Boolean).slice(0, 6).join(' ');
const angulos = doRev.map((a, i) => {
  const c = doCopy[i], x = {};
  for (const k of Object.keys(a)) x[k] = a[k] || c[k];
  const nome = x.nome;
  x.principal_a = cpTrava(x.principal_a, V, `${nome} (texto A)`, trava) || cpTrava(c.principal_a, V, `${nome} (texto A do copywriter)`, trava)
    || `${d.produto}${d.cidade ? ' em ' + d.cidade : ''}. ${d.oferta ? d.oferta.replace(/[.!]*$/, '. ') : ''}${d.preco ? d.preco + '. ' : ''}${O.botao}!`;
  x.principal_b = cpTrava(x.principal_b, V, `${nome} (texto B)`, trava) || x.principal_a;
  x.titulo = cpTrava(x.titulo, V, `${nome} (título)`, trava) || cpL(d.produto, 40);
  x.descricao = cpTrava(x.descricao, V, `${nome} (descrição)`, trava) || cpL(d.oferta || d.negocio, 30);
  x.frase_arte = frase6(cpTrava(x.frase_arte, V, `${nome} (frase da arte)`, trava)) || frase6(x.titulo);
  if (!O.botoes.includes(x.botao)) { if (x.botao && x.botao !== O.botao) trava.push(`${nome}: botão "${x.botao}" não serve para ${O.nome}, ficou "${O.botao}"`); x.botao = O.botao; }
  x.codigo = x.tipo.toUpperCase().slice(0, 4);
  x.mensagem_whatsapp = `Olá! Vi o anúncio de ${d.negocio} sobre ${d.produto.toLowerCase()} e quero saber mais. (anúncio ${x.codigo})`;
  x.imagem = x.imagem || `Bright professional advertising photo for ${d.produto} (${d.segmento || d.negocio}), ${x.tipo === 'dor' ? 'showing the everyday problem it solves' : x.tipo === 'desejo' ? 'showing the happy result' : 'showing the product or service clearly'}`;
  return x;
});
// página de destino (cadastros, loja e quem quiser medir os cliques)
const pg = rv && rv.pagina && typeof rv.pagina === 'object' ? rv.pagina : C.textos.pagina || {};
const pagina = {
  titulo: cpTrava(cpL(pg.titulo, 80), V, 'página (título)', trava) || cpL(d.produto, 80),
  subtitulo: cpTrava(cpL(pg.subtitulo, 200), V, 'página (subtítulo)', trava) || cpL(d.descricao, 200),
  bullets: (Array.isArray(pg.bullets) ? pg.bullets : []).map((b, i) => cpTrava(cpL(b, 140), V, `página (vantagem ${i + 1})`, trava)).filter(Boolean).slice(0, 5),
  faq: (Array.isArray(pg.faq) ? pg.faq : []).filter(f => f && typeof f === 'object').map((f, i) => ({ p: cpL(f.p, 140), r: cpTrava(cpL(f.r, 400), V, `página (dúvida ${i + 1})`, trava) })).filter(f => f.p && f.r).slice(0, 4),
  cta: cpL(pg.cta, 34) || (op.objetivo === 'cadastros' ? 'Quero me cadastrar' : op.objetivo === 'loja' ? 'Ver como chegar' : O.botao),
};
if (pagina.bullets.length < 2) pagina.bullets = [d.diferencial, d.oferta].map(x => cpL(x, 140)).filter(Boolean);
// links com UTM: cada anúncio (ângulo) em cada público tem o seu (o painel mostra quem trouxe visita e cadastro)
const utm = (base, a, c) => base + (base.includes('?') ? '&' : '?') + `utm_source=facebook&utm_medium=paid&utm_campaign=${V.id}&utm_content=${a.tipo}&utm_term=${cpSlug(c.nome).slice(0, 30)}`;
const links = [];
for (const c of E.conjuntos) for (const a of angulos) {
  links.push({ conjunto: c.nome, angulo: a.tipo, nome: `${c.nome} · ${a.nome}`,
    link: op.objetivo === 'vendas' ? utm(op.site, a, c) : op.objetivo === 'mensagens' ? `https://wa.me/${op.whatsapp}?text=${encodeURIComponent(a.mensagem_whatsapp)}` : utm(V.link, a, c) });
}
// imagens: as fotos do anunciante (em rodízio) ou uma da IA por anúncio
const pedidos = op.fotos.length ? [] : angulos.map(a => ({ nome: 'img-' + a.tipo, uso: 'anúncio ' + a.nome,
  prompt: a.imagem + '. Square photo, real-life advertising look, natural light, sharp focus. Absolutely no text, letters, numbers, logos or watermarks. No before-and-after comparison.' }));
const problemas = rv && Array.isArray(rv.problemas) ? rv.problemas.map(p => cpT(p, 220)).filter(p => p && !/\bok\b|est[aá] corret|est[aã]o corret|nenhum problema|sem altera|dentro do limite/i.test(p)).slice(0, 6) : [];
return [{ json: { angulos, pagina, links, problemas, trava: [...new Set(trava)].slice(0, 10), revisor_veio: !!(rv && doRev.some(a => a.principal_a)),
  com_fotos: op.fotos.length > 0, precisa_ia: !op.fotos.length && op.imagens, pedidos } }];

// as fotos do anunciante vão para a pasta da campanha (foto-1, foto-2…); as artes usam em rodízio
const V = $('🧩 Confere o pedido').first().json;
return [{ json: { corpo: JSON.stringify({ area: 'decks', deck: V.id, imagens: V.op.fotos.map((b64, i) => ({ nome: 'foto-' + (i + 1), b64 })) }) } }];

// Junta as imagens que a IA desenhou (uma por pedido, na mesma ordem) num pedido só para a oficina guardar na pasta da campanha.
const V = $('🧩 Confere o pedido').first().json;
const pedidos = $('🧩 Lista as imagens').all().map(i => i.json);
const res = $input.all().map(i => i.json);
const imagens = [], falhas = [];
pedidos.forEach((p, i) => {
  const r = res[i] || {}, b64 = r.data && r.data[0] && r.data[0].b64_json;
  if (b64) imagens.push({ nome: p.nome, b64 }); else falhas.push({ nome: p.nome, erro: String((r.error && (r.error.message || r.error)) || r.message || 'sem imagem').slice(0, 160) });
});
return [{ json: { corpo: JSON.stringify({ area: 'decks', deck: V.id, imagens }), geradas: imagens.length, falhas } }];

// Pedido da revisora das imagens (IA com visão): cada miniatura com o anúncio para o qual ela foi feita.
const V = $('🧩 Confere o pedido').first().json;
const g = $('🛠️ Oficina: guarda as imagens').first().json || {};
const pedidos = $('🧩 Lista as imagens').all().map(i => i.json);
const guardadas = Array.isArray(g.imagens) ? g.imagens : [];
const conteudo = [{ type: 'text', text: `Você revisa imagens geradas por IA para anúncios no Facebook e no Instagram de "${V.dados.negocio}" (${V.dados.produto}). O texto do anúncio vai por cima, na parte de baixo da imagem.
Reprove (ok=false) se tiver: texto, letras ou números legíveis; logotipo ou marca; rosto ou mão deformados; objeto derretido ou sem sentido; algo que não combina com o produto; "antes e depois"; corpo exposto ou sensual; conteúdo que o Meta recusa.
PODE passar: pessoa de longe ou desfocada; pequenos defeitos que ninguém nota. Refazer custa 1 minuto: só reprove o que estragaria o anúncio.
RETORNE SOMENTE JSON: {"imagens":[{"nome":"img-dor","ok":true,"problema":"o que está errado, em poucas palavras"}]}` }];
for (const im of guardadas) {
  const p = pedidos.find(x => x.nome === im.nome) || {};
  conteudo.push({ type: 'text', text: `IMAGEM ${im.nome} (${p.uso || ''}) — pedido: ${String(p.prompt || '').slice(0, 300)}` });
  conteudo.push({ type: 'image_url', image_url: { url: 'data:image/jpeg;base64,' + im.mini } });
}
return [{ json: { corpo: JSON.stringify({ model: 'antigravity/gemini-3-flash', max_tokens: 1200, temperature: 0.1, messages: [{ role: 'user', content: conteudo }] }), qtd: guardadas.length } }];

function parseJSON(txt) {
  const s = String(txt || '').replace(/^\s*```(?:json)?\s*/i, '').replace(/```\s*$/i, '').trim();
  try { return JSON.parse(s); } catch (e) {}
  const a = s.indexOf('{'), b = s.lastIndexOf('}');
  if (a > -1 && b > a) { try { return JSON.parse(s.slice(a, b + 1)); } catch (e) {} }
  return null;
}

// Lê a revisão das imagens. Refaz UMA vez: a reprovada (com o defeito no pedido) e a que não veio.
const pedidos = $('🧩 Lista as imagens').all().map(i => i.json);
const g = $('🛠️ Oficina: guarda as imagens').first().json || {};
const guardadas = (Array.isArray(g.imagens) ? g.imagens : []).map(x => x.nome);
const r = $input.first().json || {};
let v = null;
try { v = parseJSON(r.choices && r.choices[0] && r.choices[0].message && r.choices[0].message.content); } catch (e) {}
const notas = v && Array.isArray(v.imagens) ? v.imagens : [];
const refazer = [];
for (const p of pedidos) {
  const nota = notas.find(x => x && x.nome === p.nome);
  if (!guardadas.includes(p.nome)) refazer.push(Object.assign({}, p, { motivo: 'não veio', nome: p.nome + '-r1' }));
  else if (nota && nota.ok === false) refazer.push(Object.assign({}, p, { motivo: String(nota.problema || 'defeito').slice(0, 120), nome: p.nome + '-r1',
    prompt: p.prompt + ' Avoid this problem from the previous attempt: ' + String(nota.problema || 'visual defects').slice(0, 120) + '.' }));
}
const reprovadas = notas.filter(x => x && x.ok === false).map(x => ({ nome: x.nome, problema: String(x.problema || '').slice(0, 120) }));
if (!refazer.length) return [{ json: { refazer: false, viu: !!v, reprovadas } }];
return refazer.map(x => ({ json: Object.assign({}, x, { refazer: true, viu: !!v, reprovadas }) }));

// Junta as imagens que a IA desenhou (uma por pedido, na mesma ordem) num pedido só para a oficina guardar na pasta da campanha.
const V = $('🧩 Confere o pedido').first().json;
const pedidos = $('🧩 Lê a revisão das imagens').all().map(i => i.json);
const res = $input.all().map(i => i.json);
const imagens = [], falhas = [];
pedidos.forEach((p, i) => {
  const r = res[i] || {}, b64 = r.data && r.data[0] && r.data[0].b64_json;
  if (b64) imagens.push({ nome: p.nome, b64 }); else falhas.push({ nome: p.nome, erro: String((r.error && (r.error.message || r.error)) || r.message || 'sem imagem').slice(0, 160) });
});
return [{ json: { corpo: JSON.stringify({ area: 'decks', deck: V.id, imagens }), geradas: imagens.length, falhas } }];

// Regras da campanha de anúncios (as mesmas na criação, na revisão, na página de destino e no painel).
// corta no fim de uma frase (ou de uma palavra, com "…"): nunca no meio da palavra
const cpT = (v, max) => {
  const s = String(v ?? '').replace(/\s+/g, ' ').trim();
  if (s.length <= max) return s;
  const c = s.slice(0, max), fim = Math.max(c.lastIndexOf('. '), c.lastIndexOf('! '), c.lastIndexOf('? '));
  if (fim >= max * 0.55) return c.slice(0, fim + 1);
  const esp = c.lastIndexOf(' ');
  return (esp >= max * 0.55 ? c.slice(0, esp) : c.slice(0, max - 1)).replace(/[\s,;:.–—-]+$/, '') + '…';
};
const cpL = (v, max) => cpT(v, max).replace(/[<>{}]/g, '');
// texto com parágrafos (texto principal do anúncio): mantém as quebras de linha
const cpP = (v, max) => {
  const s = String(v ?? '').replace(/\r/g, '').replace(/[<>{}]/g, '').split('\n').map(l => l.replace(/[ \t]+/g, ' ').trim()).join('\n').replace(/\n{3,}/g, '\n\n').trim();
  return s.length <= max ? s : cpT(s.replace(/\n+/g, ' '), max);
};
const cpEsc = v => String(v ?? '').replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
const cpNum = v => {
  let s = String(v ?? '').replace(/[^\d,.]/g, '');
  if (!s) return null;
  if (/,\d{1,2}$/.test(s)) s = s.replace(/\./g, '').replace(',', '.'); else if (/^\d{1,3}(\.\d{3})+$/.test(s)) s = s.replace(/\./g, ''); else s = s.replace(/,/g, '');
  const n = Number(s); return isFinite(n) && n >= 0 ? Math.round(n * 100) / 100 : null;
};
const cpReal = n => 'R$ ' + Number(n || 0).toFixed(2).replace('.', ',').replace(/\B(?=(\d{3})+(?!\d))/g, '.');
const cpHex = h => { h = String(h || '').replace('#', ''); return [0, 2, 4].map(i => parseInt(h.slice(i, i + 2), 16) || 0); };
const cpLum = h => cpHex(h).map(v => { v /= 255; return v <= 0.03928 ? v / 12.92 : Math.pow((v + 0.055) / 1.055, 2.4); }).reduce((a, v, i) => a + v * [0.2126, 0.7152, 0.0722][i], 0);
const cpContraste = (a, b) => { const x = cpLum(a), y = cpLum(b); return (Math.max(x, y) + 0.05) / (Math.min(x, y) + 0.05); };
const cpMistura = (a, b, k) => { const x = cpHex(a), y = cpHex(b); return '#' + x.map((v, i) => Math.round(v + (y[i] - v) * k).toString(16).padStart(2, '0')).join('').toUpperCase(); };
function cpTokens(cor) {
  const c = /^#[0-9a-fA-F]{6}$/.test(cor || '') ? String(cor).toUpperCase() : '#1F6FEB';
  let forte = c;
  for (let i = 0; i < 16 && cpContraste(forte, '#FFFFFF') < 4.5; i++) forte = cpMistura(forte, '#000000', 0.12);
  return { cor: c, forte, tinta: cpContraste('#FFFFFF', forte) >= 4.5 ? '#FFFFFF' : '#111111', suave: cpMistura(c, '#FFFFFF', 0.9), linha: cpMistura(c, '#FFFFFF', 0.72), escuro: cpMistura(forte, '#000000', 0.55) };
}
const cpSemAcento = t => String(t || '').normalize('NFD').replace(/[̀-ͯ]/g, '').toLowerCase();
const cpSlug = t => cpSemAcento(t).replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '');
// frases de um texto ("Av. Brasil", "Dr. João" não terminam frase)
const CP_ABREV = /(?:^|[\s(])(?:av|r|dr|dra|sr|sra|sta|sto|prof|profa|n|nº|jd|pq|al|km|tel|cel|obs|seg|ter|qua|qui|sex|s[áa]b|dom|etc)\.$/i;
const cpFrases = t => {
  const out = [];
  for (const p of String(t || '').split(/(?<=[.!?…])\s+/)) { if (out.length && CP_ABREV.test(out[out.length - 1])) out[out.length - 1] += ' ' + p; else out.push(p); }
  return out.map(x => x.trim()).filter(Boolean);
};
// valores em R$ escritos num texto (em centavos)
