    if (s > 0) { nome = l.slice(0, s); resto = l.slice(s).replace(/^\s*(?:[:;,\t]|[–-])\s*/, ''); }
    else { const m = l.match(/^(.*?)\s*(?=(?:R\$\s*)?\d)/); nome = m ? m[1] : ''; resto = m ? l.slice(m[0].length) : ''; }
