${cp.estrategia.metas.texto}
NÚMEROS QUE O ANUNCIANTE COLOU (calculados pelo sistema; NÃO recalcule, use estes):
${tabela.map(r => `- ${r.nome}: gasto ${cpReal(r.gasto || 0)}, impressões ${fmt(r.impressoes)}, cliques ${fmt(r.cliques)}, resultados ${fmt(r.resultados)}, CTR ${fmt(r.ctr)}%, CPC ${r.cpc === null ? '—' : cpReal(r.cpc)}, custo por resultado ${r.cpr === null ? '—' : cpReal(r.cpr)} ➜ VEREDITO DO SISTEMA: ${r.veredito} (${r.motivo})${r.alerta ? ' · ' + r.alerta : ''}`).join('\n')}
TOTAL: gasto ${cpReal(tot.gasto)}, ${tot.resultados} resultados, custo por resultado ${tot.cpr === null ? '—' : cpReal(tot.cpr)}
ÂNGULOS DOS ANÚNCIOS: ${cp.angulos.map(a => a.nome).join(', ')}`;
return [{ json: { valido: true, id: cp.id, tabela, totais: tot, meta, base_meta, texto_ia } }];

