<div class="rolar"><table><thead><tr><th>Público</th><th>Anúncio</th><th>Link</th></tr></thead><tbody>${cp.links.map(l => linha([l.conjunto, nomes[l.angulo] || l.angulo, { v: l.link, h: `<button class="mini" type="button" data-copiar="${E(l.link)}">📋 Copiar</button> <small>${E(cpT(l.link, 70))}</small>` }])).join('')}</tbody></table></div></div>
